<template>
  <f-btn
    v-if="isButtonVisible"
    :label="formBuilderConfigModel[fieldName].label"
    :disable="isReadOnly"
    class="full-width q-mt-sm"
    :class="canDisabled && !enableExportButton ? 'disabled' : ''"
    @click="
      $event.stopPropagation();
      inputClicked(fieldName);
    "
  >
    <q-tooltip v-if="canDisabled && hasErrors">
      Following fields need to be validated before export:<br />
      <div v-for="item in fieldErrors" :key="item">{{ item }}<br /></div>
    </q-tooltip>
  </f-btn>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS, isDocTypeInvoice } from 'src/constants';
import { useFormBuilderStore, useDocumentStore } from 'src/store/main';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
import { objLen } from 'src/utils/general';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_button_type: {
      type: String,
      default: '',
    },
  },
  emits: ['inputClicked', 'updateModel'],
  computed: {
    isButtonVisible: function () {
      if (
        this.isFormBuilderMode ||
        formBuilderInputTypes.EXPORT_BUTTON !== this.currentField.fieldType
      ) {
        return true;
      }

      // parent component to handle visibility
      if (this.show_button_type === this.currentField.fieldType) {
        return true;
      } else if (this.show_button_type !== '') {
        return false;
      }

      return true;
    },
    hasErrors: function () {
      return objLen(this.fieldErrors) > 0;
    },
  },

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    if (
      !this.isFormBuilderMode &&
      this.formBuilderConfigModel[this.fieldName].exportType ==
        CONSTANTS.export &&
      isDocTypeInvoice(this.doctype)
    ) {
      this.canDisabled = true;
    }
  },
  methods: {
    inputClicked(fieldName: string) {
      if (this.canDisabled && !this.enableExportButton) {
        return;
      }
      this.$emit('inputClicked', fieldName);
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { fieldErrors, enableExportButton, doctype } = storeToRefs(doc_store);

    const form_builder_store = useFormBuilderStore();
    const { formBuilderModel, isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);
    return {
      doctype,
      fieldErrors,
      formBuilderModel,
      isFormBuilderMode,
      enableExportButton,
      formBuilderConfigModel,

      canDisabled: ref(false),
    };
  },
});
</script>
