<template>
  <f-btn
    v-if="is_button_visible"
    :label="formBuilderConfigModel[fieldName].label"
    class="full-width q-mt-sm"
    @click="clickEvent"
  >
    <q-icon
      v-if="isFormBuilderMode && !isPoSettingActivate(doctype)"
      flat
      dense
      name="error"
      size="24px"
      color="white"
    >
      <q-tooltip class="bg-red" anchor="bottom right" self="top right">
        {{ $t('module_disabled') }}
      </q-tooltip>
    </q-icon>
  </f-btn>
  <q-dialog v-model="showConfirmRemoveConnectionsDialog" persistent>
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          {{ $t('confirm') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">
          {{ $t('confirm_po_match_connection_removal') }}
        </span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          :label="$t('proceed_without_save_extraction_table')"
          v-close-popup
          @click="proceedWithoutRemovePOConnection()"
        />
        <f-btn
          :label="$t('proceed_with_remove_po_match_connection')"
          v-close-popup
          @click="proceedWithRemovePOConnection()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import poActionsUtil from 'src/utils/poActionsUtil';
import { notify } from 'src/components/notifications/notify';
import {
  useFormBuilderStore,
  useDocumentStore,
  useDocLockStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_button_type: {
      type: String,
      default: '',
    },
    class: {
      type: String,
      default: '',
    },
  },
  emits: ['inputClicked', 'updateModel'],
  mixins: [poActionsUtil, helperMixin],
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
    this.isButtonVisible();
    document.addEventListener('delete_table', this.reInitButton);
  },
  unmounted: function () {
    document.removeEventListener('delete_table', this.reInitButton);
  },
  computed: {},
  methods: {
    proceedWithRemovePOConnection() {
      this.showConfirmRemoveConnectionsDialog = false;
      this.is_extracted_table_update = false;
      this.record.po_multi_matched = [];
      // Resume
      this.resumeAfterConfirmDialog();
    },
    proceedWithoutRemovePOConnection() {
      this.showConfirmRemoveConnectionsDialog = false;
      this.is_extracted_table_update = false;
      this.setExtractionTableDataFromCache();
      // Resume
      this.resumeAfterConfirmDialog();
    },
    async clickEvent(event?: any) {
      if (event) {
        event.stopPropagation?.();
      }
      if (this.isFormBuilderMode) {
        this.$emit('inputClicked', this.fieldName);
        return;
      }

      if (this.isReadOnly) {
        const po_match_route = await this.getPOUrl(this.record.doc_type);
        this.$router.push(po_match_route + this.record.doc_id);
        return;
      }

      if (this.tb_version === null) {
        return;
      }

      if (
        this.record.po_multi_matched &&
        this.record.po_multi_matched.length > 0 &&
        this.is_extracted_table_update
      ) {
        // Show popup
        this.showConfirmRemoveConnectionsDialog = true;
        this.resumeAfterConfirmDialog = this.clickEvent;
        return;
      }

      this.showLoading();

      const saving_data_alert_id = notify.info(this.$t('saving_data'));
      const response: dynamicObj = await this.saveAndValidate();
      notify.dismiss(saving_data_alert_id);
      if (response.success === false) {
        const event = new CustomEvent('display_fields_errors', {});
        document.dispatchEvent(event);
        notify.error(response.message);
        this.hideLoading();
        return;
      }

      if (this.user_settings[CONSTANTS.po_auto_match_and_export]) {
        this.execute_auto_export = true;
      }

      this.hideLoading();

      const po_match_route = await this.getPOUrl(this.record.doc_type);
      this.$router.push(po_match_route + this.record.doc_id);
    },

    async isButtonVisible() {
      if (this.isFormBuilderMode) {
        this.is_button_visible = true;
        return;
      }

      if (this.show_button_type === this.currentField.fieldType) {
        this.is_button_visible = true;
        return;
      } else if (this.show_button_type !== '') {
        this.is_button_visible = false;
        return;
      }

      if (!this.hasTable()) {
        this.is_button_visible = false;
        return;
      }

      if (
        (await this.isPoSettingActivate(this.doctype)) &&
        this.isPoIconAllowed(this.record.status, this.tb_version)
      ) {
        this.is_button_visible = true;
        return;
      }
      this.is_button_visible = false;
    },

    reInitButton() {
      this.isButtonVisible();
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { formBuilderModel, isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record, doctype, tb_version, is_extracted_table_update } =
      storeToRefs(doc_store);
    const { saveAndValidate, hasTable, setExtractionTableDataFromCache } =
      doc_store;

    const doc_lock_store = useDocLockStore();
    const { hasActionAcquiredLock, releaseDocLock } = doc_lock_store;

    const settings_store = useSettingStore();
    const { user_settings, execute_auto_export } = storeToRefs(settings_store);

    return {
      releaseDocLock,
      saveAndValidate,
      is_extracted_table_update,
      setExtractionTableDataFromCache,
      hasActionAcquiredLock,
      hasTable,

      user_settings,
      execute_auto_export,

      tb_version,
      doctype,
      record,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      is_button_visible: ref(false),
    };
  },
  data() {
    return {
      showConfirmRemoveConnectionsDialog: false,
      resumeAfterConfirmDialog: ref(),
    };
  },
});
</script>
