<template>
  <div class="full-width">
    <q-markup-table
      flat
      class="group_checkboxes_tbl overflow-visible border-bottom"
    >
      <thead
        v-for="(tableHeaderRow, headerRowIndex) in formBuilderConfigModel[
          fieldName
        ].tableHeaderRows"
        :key="headerRowIndex"
      >
        <tr>
          <th
            v-for="(tableHeaderColumn, headerColumnIndex) in tableHeaderRow"
            :key="headerColumnIndex"
            class="border-left"
            :class="headerColumnIndex == 0 ? ' text-left ' : ' center '"
          >
            {{ tableHeaderColumn }}
          </th>
          <th v-if="isFormBuilderMode" class="center border-left">
            <q-btn
              round
              color="primary"
              icon="settings"
              size="xs"
              class="h-m-5 float-right"
              @click="loadSettings(Number(headerRowIndex), Number(headerColumnIndex), true)"
            >
              <q-tooltip>{{ $t('settings._label') }}</q-tooltip>
            </q-btn>
          </th>
        </tr>
      </thead>

      <tbody>
        <template
          v-for="(tableBodyRow, bodyRowsIndex) in formBuilderConfigModel[
            fieldName
          ].tableBodyRows"
          :key="bodyRowsIndex"
        >
          <tr>
            <template
              v-for="(tableBodyColumn, bodyColumnIndex) in tableBodyRow"
              :key="bodyColumnIndex"
            >
              <td
                class="text-left border-left"
                v-if="tableBodyColumn.isLabelArea"
                @click="loadSettings(Number(bodyRowsIndex), Number(bodyColumnIndex), false)"
              >
                {{ tableBodyColumn.label }}
              </td>
              <td
                v-else
                class="center border-left group-checkbox-td"
                @click="loadSettings(Number(bodyRowsIndex), Number(bodyColumnIndex), false)"
                :class="
                  formBuilderConfigModel[fieldName].tableBodyRows[
                    bodyRowsIndex
                  ][bodyColumnIndex].isDisabled
                    ? ' bg-disable '
                    : ' '
                "
              >
                <q-checkbox
                  :id="tableBodyColumn.name"
                  child_type="checkbox"
                  :disable="
                    !isFormBuilderMode &&
                    (isReadOnly ||
                      formBuilderConfigModel[fieldName].tableBodyRows[
                        bodyRowsIndex
                      ][bodyColumnIndex].isDisabled)
                  "
                  @update:model-value="
                    inputValueChanges(
                      $event,
                      tableBodyColumn.name,
                      Number(bodyRowsIndex),
                      Number(bodyColumnIndex),
                    )
                  "
                  @focus="focusEvent"
                  @keydown.enter="
                    (event: any) => {
                      keydownEvent(event, tableBodyColumn.name);
                    }
                  "
                  v-model="
                    formBuilderModel[tableBodyColumn.name].formatted_value
                  "
                  size="30px"
                  color="grey-6"
                  :class="
                    tableBodyColumn.name +
                    ' ' +
                    getElementBorder(
                      formBuilderConfigModel[tableBodyColumn.name].color,
                    )
                  "
                />
              </td>
            </template>
            <td v-if="isFormBuilderMode" class="center border-left">
              <q-btn
                round
                color="primary"
                icon="delete"
                size="xs"
                class="h-m-5 float-right"
                @click="deleteRow(Number(bodyRowsIndex))"
              >
                <q-tooltip>{{ $t('delete') }}</q-tooltip>
              </q-btn>
            </td>
          </tr>
        </template>
      </tbody>
    </q-markup-table>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import documentUtil from 'src/utils/documentUtil';
import { useFormBuilderStore } from 'src/store/main';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';

export default defineComponent({
  name: 'TableOfCheckboxes',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['updateModel', 'inputValueChanges'],
  mixins: [documentUtil],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  methods: {
    loadSettings(rowIndex: number, columnIndex: number, isColumnMode: boolean) {
      if (!this.isFormBuilderMode) {
        return;
      }

      this.activeTab = 'element_properties';
      this.activeFieldName = this.fieldName;

      // e.stopPropagation();
      const event = new CustomEvent('load_settings', {
        detail: {
          rowIndex: rowIndex,
          columnIndex: columnIndex,
          isColumnMode: isColumnMode,
        },
      });
      document.dispatchEvent(event);
    },
    deleteRow(rowIndex: number) {
      for (let tableBodyColumn of this.formBuilderConfigModel[this.fieldName]
        .tableBodyRows) {
        delete this.formBuilderModel[tableBodyColumn.name];
      }

      this.formBuilderConfigModel[this.fieldName].tableBodyRows.splice(
        rowIndex,
        1,
      );
    },

    inputValueChanges(
      e: any,
      field_name: string,
      rowIndex: number,
      columnIndex: number,
    ) {
      const is_entered_pressed = (<any>window).event.key == 'Enter';
      if (is_entered_pressed) {
        const current_value = this.formBuilderModel[field_name].formatted_value;
        setTimeout(() => {
          this.formBuilderModel[field_name].formatted_value = current_value;
          this.emitinputValueChanges(field_name);
        }, 50);
        this.triggerMoveToNextFieldEvent(field_name);
        return;
      }

      this.emitinputValueChanges(field_name);

      this.loadSettings(rowIndex, columnIndex, false);
    },

    emitinputValueChanges(field_name: string) {
      this.$emit(
        'inputValueChanges',
        field_name,
        formBuilderInputTypes.TABLE_OF_CHECKBOXES,
      );
    },

    triggerMoveToNextFieldEvent(field_name: string) {
      if (this.is_focus_event) {
        this.is_focus_event = false;
        return;
      }
      const event = new CustomEvent('move_to_next_field', {
        detail: field_name,
      });
      document.dispatchEvent(event);
    },

    keydownEvent(e: any, field_name: string) {
      this.is_focus_event = false;
      this.triggerMoveToNextFieldEvent(field_name);
    },

    focusEvent() {
      this.is_focus_event = true;
      setTimeout(() => {
        this.is_focus_event = false;
      }, 500);
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderConfigModel,
      isFormBuilderMode,
      formBuilderModel,
      activeFieldName,
      activeTab,
    } = storeToRefs(form_builder_store);
    return {
      activeTab,
      activeFieldName,
      isFormBuilderMode,
      formBuilderModel,
      formBuilderConfigModel,
      is_focus_event: ref(false),
    };
  },
});
</script>

