<template>
  <div
    class="full-width"
    :class="isFormBuilderMode && showTabIndex ? 'position-relative' : ''"
  >
    <q-option-group
      :id="fieldName"
      child_type="multi_checkbox"
      inline
      color="primary"
      type="checkbox"
      v-model="formBuilderModel[fieldName].groupList"
      :options="formBuilderConfigModel[fieldName].options"
      :tabindex="formBuilderConfigModel[fieldName].tabIndex"
      @update:model-value="
        (newVal) => {
          inputValueChanges($event, newVal);
        }
      "
    />
    <q-badge
      v-if="isFormBuilderMode && showTabIndex"
      color="orange"
      text-color="black"
      :class="isFormBuilderMode && showTabIndex ? 'checkbox-badge' : ''"
      :label="formBuilderConfigModel[fieldName].tabIndex"
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';

export default defineComponent({
  name: 'MultiCheckBox',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['inputValueChanges', 'updateModel'],
  mixins: [displayFieldLabel, formBuilderHelper],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  methods: {
    inputValueChanges(e: any, newVal: any) {
      if (!e) {
        e = window.event;
      }

      if (e.stopPropagation) {
        e.stopPropagation();
      }

      if (this.isFormBuilderMode) {
        this.formBuilderModel[this.fieldName].groupList = [];
      } else {
        if (this.formBuilderModel[this.fieldName].groupList.length > 1) {
          this.formBuilderModel[this.fieldName].groupList.splice(0, 1);
        }
      }

      this.$emit('inputValueChanges', this.fieldName, 'checkbox');
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      showTabIndex,
    } = storeToRefs(form_builder_store);
    return {
      showTabIndex,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
    };
  },
});
</script>
